import type { MapRegion } from '@/data/animal-details';

/**
 * Zasięg występowania każdego zwierzęcia — sekcja „Gdzie spotkasz" na karcie.
 *
 * Jedno źródło prawdy dla mapy i podpisu pod nią. Wpisy zweryfikowane gatunek
 * po gatunku (09.2026); poprzednio zasięg wyliczał się z tagów wypraw, przez co
 * np. niedźwiedź polarny trafiał „do Arktyki i Antarktydy", a tapir czaprakowy
 * do Ameryki Pd.
 *
 * Zasady:
 *  - `polska` tylko wtedy, gdy zwierzę naprawdę żyje w Polsce na wolności
 *    (także w polskiej części Bałtyku);
 *  - zwierzęta domowe i hodowlane → `worldwide`, a opis mówi, skąd pochodzą;
 *  - gatunki wymarłe → miejsca znalezisk skamieniałości;
 *  - UWAGA: część id jest historyczna i nie pasuje do gatunku
 *    (np. `monarch_butterfly` to cytrynek) — liczy się `name_pl` zwierzęcia.
 */
export type AnimalRange = {
  regions: MapRegion[];
  habitat_pl: string;
};

const r = (regions: MapRegion[], habitat_pl: string): AnimalRange => ({ regions, habitat_pl });

